package servicio;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.sql.Connection;import java.time.*;import org.junit.jupiter.api.*;import dao.*;import negocio.*;
class IdentidadDeportivaOperacionesTest {PerfilJugadorDAO p;CategoriaDeportivaDAO c;JugadorCategoriaDAO h;Connection x;IdentidadDeportivaService s;@BeforeEach void init(){p=mock(PerfilJugadorDAO.class);c=mock(CategoriaDeportivaDAO.class);h=mock(JugadorCategoriaDAO.class);x=mock(Connection.class);s=new IdentidadDeportivaService(p,c,h,()->x);}@Test void vinculaProvisionalComoAdministrador()throws Exception{PerfilJugador perfil=new PerfilJugador();perfil.setId(2);perfil.setEstado(EstadoPerfilJugador.PROVISIONAL);perfil.setNombrePublico("Ana");when(p.buscar(x,2)).thenReturn(perfil);PerfilJugador r=s.vincularCliente(2,8,"Ana",4,true);assertEquals(EstadoPerfilJugador.DEFINITIVO,r.getEstado());assertEquals(8,r.getClienteId());assertTrue(r.isVinculacionRevisada());verify(x).commit();}@Test void operadorNoPuedeVincular(){assertThrows(SecurityException.class,()->s.vincularCliente(2,8,"Ana",4,false));}@Test void actualizaPreferencias(){PerfilJugador perfil=new PerfilJugador();perfil.setId(2);perfil.setEstado(EstadoPerfilJugador.PROVISIONAL);perfil.setNombrePublico("Ana");when(p.buscar(x,2)).thenReturn(perfil);s.actualizarPerfil(2,"Ana P",PosicionJugador.DRIVE,true,true);verify(p).guardar(x,perfil);assertTrue(perfil.isAceptaInvitaciones());}@Test void suspendeCategoriaVigente()throws Exception{PerfilJugador perfil=new PerfilJugador();perfil.setId(2);JugadorCategoria vigente=new JugadorCategoria();vigente.setFechaDesde(LocalDate.of(2026,1,1));when(p.buscar(x,2)).thenReturn(perfil);when(h.buscarVigente(x,2)).thenReturn(vigente);s.cerrarCategoria(2,LocalDate.of(2026,2,1),EstadoJugadorCategoria.SUSPENDIDA,"Revisión",null,4L,true);verify(h).cerrarVigente(x,2,LocalDate.of(2026,2,1),EstadoJugadorCategoria.SUSPENDIDA,"Revisión",null,4L);verify(x).commit();}}
